window.kbPageData["views/entry/k-6530391f8a8ffb57"] = {"key":"entry/k-6530391f8a8ffb57","state":{"route":"entry/k-6530391f8a8ffb57"},"node":{"id":"k-6530391f8a8ffb57","mode":"k","title":"差集占比的下界","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["同一总体中仅属于第一集合的占比下界为两集合占比之差与零的较大值"],"qs":["江苏 2023 A类 行测#130"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"同一总体中，若有两类特征的人群占比分别为 p 和 q，则只具有第一类特征的人群占比至少为 p−q 与 0 中的较大值。","review":{"definition":"同一总体中，若有两类特征的人群占比分别为 p 和 q，则只具有第一类特征的人群占比至少为 p−q 与 0 中的较大值。","explanation":"只具有第一类特征的人群占比等于 p 减去两类人群的重叠占比。重叠占比最多等于较小的一类，因此两类重叠最多时，差集占比最小。本题中，假设有“放大图标”需求的受访者同时都有“放大字体”需求，只有“放大字体”需求而无“放大图标”需求的人数达到最小。按材料所列比例估算，下界约为 1107×（55.6%−33.9%）≈240 人，足以推出 B 项的“不少于230人”。","references":[],"evidence":"有放大字体、放大图标需求的受访者的占比分别为55.6%、33.9%","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#130":{"paper":"江苏 2023 A类 行测","n":130,"mod":"资料分析","src":["22304fe4c340e19d7902.pdf",29],"asrc":["be17f9afe070cf13a0fb.pdf",40],"card":"bd6fbd470ee2a0834b80a7c3","links":[{"id":"k-6530391f8a8ffb57","role":"解题依据","why":"交集最大时，仅属于第一集合的人数最少，交集人数至多等于较小集合的人数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-6530391f8a8ffb57":[["江苏 2023 A类 行测#130"]]}};
